package com.lqq.supportflow.knowledge.infrastructure.extraction;
import com.lqq.supportflow.knowledge.domain.DocumentTextExtractor; import java.io.InputStream; import org.apache.tika.Tika; import org.springframework.stereotype.Component;
@Component public class TikaDocumentTextExtractor implements DocumentTextExtractor { private static final int MAX_CHARS=5_000_000; private final Tika tika=new Tika(); public String extract(InputStream content,String contentType){try{String text=tika.parseToString(content);if(text.isBlank())throw new IllegalArgumentException("document contains no extractable text");if(text.length()>MAX_CHARS)throw new IllegalArgumentException("extracted document is too large");return text;}catch(IllegalArgumentException exception){throw exception;}catch(Exception exception){throw new IllegalArgumentException("cannot extract document text",exception);}}}
